#ifndef SAMPLE_TYPES_H
#define SAMPLE_TYPES_H

struct Header {
  int length;
  int flags;
};

int skip_space(const char *p);
int header_size(const struct Header *h);
int parse_header(const struct Header *h, const char *p);

#endif

functions.pseudocode:
int header_size(Header *h) {
  if (h->length < 0) {
    return 0;
  }
  return h->length;
}

int parse_header(Header *h, const char *p) {
  if (skip_space(p)) {
    return header_size(h);
  }
  return 0;
}
